// Korea University Anam campus (humanities side) package — LOCAL PREVIEW ONLY (registry status 'soon',
// not public). Data is generated by scripts/campuses/korea/build-package.mjs from Codex's pilot output.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, KOREA_PLACEMENTS, KOREA_PATHS, KOREA_AREAS, KOREA_PROVENANCE, KOREA_TERRAIN, KOREA_BUILDING_BASE, KOREA_TREELESS } from './data.js';
import { GROUND_BAKE } from './ground-bake.js';

// Relative height grid (metres, centimetre Int16) sampled bilinearly in world units; edges clamp.
const T = KOREA_TERRAIN, CM = (() => { const bin = atob(T.centimetresBase64), b = new Uint8Array(bin.length); for (let i = 0; i < b.length; i++) b[i] = bin.charCodeAt(i); return new Int16Array(b.buffer); })();
function groundHeight(x, z) {
  const fi = Math.max(0, Math.min(T.nx - 1.000001, (x / WORLD_UNITS_PER_METER - T.minE) / T.cellSize));
  const fj = Math.max(0, Math.min(T.ny - 1.000001, (-z / WORLD_UNITS_PER_METER - T.minN) / T.cellSize));
  const i = Math.floor(fi), j = Math.floor(fj), u = fi - i, v = fj - j, at = (a, b) => CM[b * T.nx + a] / 100;
  const h = (at(i, j) * (1 - u) + at(i + 1, j) * u) * (1 - v) + (at(i, j + 1) * (1 - u) + at(i + 1, j + 1) * u) * v;
  return h * WORLD_UNITS_PER_METER;
}
const insideRing = (p, ring) => { let yes = false; for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) { const a = ring[i], b = ring[j]; if ((a.z > p.z) !== (b.z > p.z) && p.x < (b.x - a.x) * (p.z - a.z) / (b.z - a.z) + a.x) yes = !yes; } return yes; };

const MODEL_IDS = Object.freeze(KOREA_PLACEMENTS.map(p => p.id));

export const KOREA = Object.freeze({
  id: 'korea',
  meta: Object.freeze({ school: '고려대학교', campus: '안암캠퍼스', short: '고려대 안암', modelNoun: '고려대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: KOREA_PLACEMENTS,
  approvedCount: KOREA_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['main', 'centralLibrary', 'westHall', 'graduateOldLibrary', 'centennialSamsung', 'lawNew']),
  startBuildingId: 'main',
  models: Object.freeze({
    manifests: Object.freeze([Object.freeze({ url: new URL('../../../assets/campuses/korea/manifest.json', import.meta.url).href, expectedIds: MODEL_IDS })]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  // Estimated relative terrain (SRTM/Mapzen 1″ + photo/plan constraints, Codex pilot/korea-anam/terrain);
  // building pads sit at their estimated entrance level.
  terrain: Object.freeze({ baseHeight: groundHeight, hills: Object.freeze([]), buildingBase: KOREA_BUILDING_BASE,
    source: 'Relative terrain estimate from public SRTM/Mapzen 1″ with photo/plan constraints; not a survey' }),
  environment: Object.freeze({
    spacePaths: Object.freeze([]),
    paths: KOREA_PATHS,
    areas: KOREA_AREAS,
    contextBuildings: Object.freeze([]),
    provenance: KOREA_PROVENANCE,
    extensionFor: () => ({ areas: [], paths: [] }),
    sourceNote: 'OSM paths and ground areas (© OpenStreetMap contributors, ODbL); widths and planting estimated',
  }),
  ground: Object.freeze({
    seed: 7171,
    skipMappedPath: () => false,
    // Open lawns and plazas (중앙광장 등) stay treeless.
    rejectTree: p => KOREA_TREELESS.some(a => insideRing(p, a.ring)),
    avenuePathId: null,
    avenueFurnitureStyle: 'garden',
    furnitureStyle: 'garden',
    lightSpacing: () => 13,
    keepRearTree: () => true,
    fountainAreaIds: Object.freeze([]),
    // The ground above pre-computed by scripts/campuses/korea/build-ground-bake.mjs (src/engine/ground-bake.js; ?ground=live builds it at load time).
    bake: GROUND_BAKE,
  }),
  scene: Object.freeze({
    background: '#b9ced9', fog: Object.freeze({ color: '#b9ced9', near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#e7eff4', ground: '#707764', intensity: 1.45 }),
    sun: Object.freeze({ color: '#fff2db', intensity: 3.1, position: Object.freeze([-100, 220, 120]), shadowSpan: 185 }),
    // Backdrop floor just under the lowest mapped ground.
    floor: Object.freeze({ color: '#758168', y: T.minHeight_m * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default KOREA;
